using System;
using System.Linq;
namespace ParadigmRealm {
public static class DiplomacyChecks {
 static void Check(bool yes,string why){if(!yes)throw new Exception("Diplomacy: "+why);}
 static World Setup(){var w=World.New(613);w.Found(w.units.First(u=>u.owner==0&&u.type==0));w.met[1]=w.met[2]=true;w.Relation(1,2).contact=true;w.gold=500;foreach(var n in w.nations)n.gold=500;return w;}
 static void Next(World w){w.turn++;w.AdvanceDiplomacy();}
 static DiplomaticOffer Offer(World w,TreatyKind kind,int a=0,int b=1){return w.Propose(new DiplomaticOffer{from=a,to=b,kind=kind,duration=10});}
 static void Resource(World w,int owner,int res){var c=w.cities.First(x=>x.owner==owner);var t=w.At(c.x,c.y);t.resource=res;t.farm=t.mine=t.road=true;w.RebuildTerritory();}
 public static void Run(){
  var w=Setup();Check(!w.AtWar(1,2),"new rivals begin at peace");w.version=6;w.war[1]=true;w.openBorders[2]=true;w.nations[2].relations=17;w.UpgradeSave();Check(w.version==21&&w.AtWar(1,2)&&w.AtWar(0,1)&&w.HasAccess(0,2)&&w.Opinion(2,0)==22&&w.Valid(),"v6 migration preserves old wars, borders and trust");w.UpgradeSave();Check(w.Opinion(2,0)==22,"migration is idempotent");
  w=Setup();w.met[1]=false;Check(!w.SendEmbassy(0,1)&&w.WarReason(0,1)!=""&&Offer(w,TreatyKind.Access).status==2,"first contact gates actions");w.met[1]=true;Check(w.SendEmbassy(0,1)&&w.gold==475&&!w.SendEmbassy(0,1)&&w.Opinion(1,0)==13,"embassy cost and one-off trust");Check(w.GiftGold(1)&&w.Opinion(1,0)==23,"gift connects to opinion");Check(Offer(w,TreatyKind.Friendship).status==1&&!w.DeclareWar(0,1),"negotiated friendship protects peace");Next(w);Check(w.EndTreaty(0,1,TreatyKind.Friendship)&&w.Grievances(1,0)==25&&w.DeclareWar(0,1),"breaking friendship has consequences before war");
  w=Setup();Check(Offer(w,TreatyKind.Friendship).status==2,"neutral friendship refused");Check(Offer(w,TreatyKind.Access).status==2,"one proposal per direction per turn");Next(w);Check(Offer(w,TreatyKind.Access).status==1&&w.HasAccess(0,1),"neutral access accepted");for(int i=0;i<10;i++)Next(w);Check(!w.HasAccess(0,1),"timed access expires");
  w=Setup();var inbound=Offer(w,TreatyKind.Access,1,0);Check(inbound.status==0&&!w.HasAccess(0,1),"AI proposal never accepts for player");Check(w.RespondToOffer(inbound.id,true)&&w.HasAccess(0,1)&&!w.RespondToOffer(inbound.id,true),"inbox accepts exactly once");Next(w);var stale=w.Propose(new DiplomaticOffer{from=2,to=0,kind=TreatyKind.Trade,askGold=450});w.gold=20;Check(!w.RespondToOffer(stale.id,true)&&stale.status==2,"stale treasury revalidated");
  w=Setup();inbound=Offer(w,TreatyKind.Access,1,0);for(int i=0;i<3;i++)Next(w);Check(inbound.status==3&&!w.RespondToOffer(inbound.id,true),"inbox expires");
  w=Setup();var refused=w.Propose(new DiplomaticOffer{from=0,to=1,kind=TreatyKind.Trade,askGold=40});Check(refused.status==2&&w.offers.Any(o=>o.to==0&&o.status==0),"AI supplies priced counteroffer");var counter=w.offers.Last();int total=w.gold+w.nations[1].gold;Check(w.RespondToOffer(counter.id,true)&&w.gold+w.nations[1].gold==total,"counteroffer money conserved");
  w=Setup();Resource(w,1,2);var trade=w.Propose(new DiplomaticOffer{from=0,to=1,kind=TreatyKind.Trade,duration=5,giveGold=50,givePerTurn=2,askResource=2});Check(trade.status==1&&w.HasResource(0,2)&&!w.HasDomesticResource(0,2),"resource imports unlock supply");Check(w.OfferProblem(new DiplomaticOffer{from=0,to=2,kind=TreatyKind.Trade,giveResource=2})!="","imports cannot be re-exported");int before=w.gold;total=w.gold+w.nations[1].gold;for(int i=0;i<5;i++){w.ProcessDiplomacyPayments();Next(w);}Check(w.gold==before-10&&w.gold+w.nations[1].gold==total&&w.contracts.Count==0&&!w.HasResource(0,2),"five-turn contract pays exactly five times and expires");
  w=Setup();Resource(w,1,2);trade=w.Propose(new DiplomaticOffer{from=0,to=1,kind=TreatyKind.Trade,giveGold=50,givePerTurn=2,askResource=2});w.gold=0;total=w.nations[1].gold;w.ProcessDiplomacyPayments();Check(w.gold==0&&w.nations[1].gold==total&&w.contracts.Count==0&&w.Grievances(1,0)>0,"default cancels without creating money");
  w=Setup();Resource(w,1,2);trade=w.Propose(new DiplomaticOffer{from=0,to=1,kind=TreatyKind.Trade,giveGold=50,askResource=2});w.At(w.cities.First(c=>c.owner==1).x,w.cities.First(c=>c.owner==1).y).mine=false;Check(!w.HasResource(0,2),"lost improvement immediately removes imported supply");w.ProcessDiplomacyPayments();Check(w.contracts.Count==0,"disconnected contract cancelled");
  w=Setup();w.ChangeTrust(1,0,60);Check(Offer(w,TreatyKind.Friendship).status==1,"trusted friendship accepted");Next(w);Check(Offer(w,TreatyKind.Alliance).status==2,"alliance technology gated");w.nations[0].tech[TechnologyCatalog.Index("laws")]=w.nations[1].tech[TechnologyCatalog.Index("laws")]=true;Next(w);Check(Offer(w,TreatyKind.Alliance).status==1&&w.HasAccess(0,1),"alliance grants access");Check(w.DeclareWar(2,1)&&w.AtWar(0,2),"defensive alliance automatically protects partner including player");
  w=Setup();w.Relation(0,1).allianceUntil=w.turn+10;w.Relation(0,2).peaceUntil=w.turn+8;Check(w.DeclareWar(2,1)&&!w.AtWar(0,2)&&w.Grievances(1,0)==15,"defensive pact cannot bypass protected truce");
  w=Setup();Check(w.DeclareWar(0,1)&&w.Grievances(1,0)==45,"surprise war grievance");Check(w.SetWar(1,false)&&!w.DeclareWar(0,1),"peace treaty blocks immediate redeclaration");for(int i=0;i<8;i++)Next(w);Check(w.DeclareWar(0,1),"truce ends after eight turns");
  w=Setup();Check(w.Denounce(0,1)&&!w.FormalWarAvailable(0,1),"formal war requires warning");for(int i=0;i<3;i++)Next(w);int grief=w.Grievances(1,0);Check(w.FormalWarAvailable(0,1)&&w.DeclareWar(0,1)&&w.Grievances(1,0)-grief==25,"formal war costs fewer grievances");var city=w.cities.First(c=>c.owner==0);int happy=w.ContentSlots(city);for(int i=0;i<6;i++)Next(w);Check(w.ContentSlots(city)==happy-1,"war weariness reduces city happiness");w.SetWar(1,false);Next(w);Check(w.warWeariness[0]==4,"peace recovers weariness");
  w=Setup();w.Relation(0,1).friendUntil=w.turn+15;w.ChangeTrust(1,0,50);w.nations[0].tech[TechnologyCatalog.Index("writing")]=w.nations[1].tech[TechnologyCatalog.Index("writing")]=true;city=w.cities.First(c=>c.owner==0);int science=w.Yield(city)[2];Check(Offer(w,TreatyKind.Research).status==1&&w.gold==475&&w.nations[1].gold==475&&w.Yield(city)[2]==science+2,"research costs both treasuries and improves actual city yield");
  w=Setup();var ca=w.cities.First(c=>c.owner==0);var cb=w.cities.First(c=>c.owner==1);w.tradeRoutes.Add(new TradeRoute{origin=ca.id,destination=cb.id,originOwner=0,destinationOwner=1});Check(w.TradeIncome(0)==3&&w.ImposeEmbargo(0,1)&&w.TradeIncome(0)==0,"embargo suspends real caravan income");for(int i=0;i<10;i++)Next(w);Check(w.TradeIncome(0)==3,"trade resumes after embargo expiry");
  w=Setup();Check(Offer(w,TreatyKind.BorderPromise).status==1,"border promise negotiated");int opinion=w.Opinion(0,1);for(int i=0;i<10;i++)Next(w);Check(w.Opinion(0,1)==opinion+5,"kept promise rewards trust");
  w=Setup();w.Relation(0,1).promiseBUntil=w.turn+10;ca=w.cities.First(c=>c.owner==0);for(int y=ca.y-1;y<=ca.y+1;y++)for(int x=ca.x+3;x<=ca.x+5;x++)w.At(x,y).terrain=0;w.Add(0,3,ca.x+3,ca.y);var settler=w.Add(1,0,ca.x+4,ca.y);w.Add(1,3,ca.x+1,ca.y);w.Reveal();Check(w.SettlementDiplomacyWarning(1,settler.x,settler.y)!=""&&w.SettlementOptions(settler).All(r=>r.diplomacyWarning==""),"AI avoids known promise-breaking settlement sites");Check(w.Found(settler)!=null&&w.Relation(0,1).promiseBUntil==0&&w.Grievances(0,1)==25,"observed nearby settlement breaks promise");
  w=Setup();w.Relation(0,1).allianceUntil=w.turn+10;w.ChangeTrust(1,0,60);Check(Offer(w,TreatyKind.JointWar).status==2,"joint war requires valid known third target");var joint=w.Propose(new DiplomaticOffer{from=0,to=1,kind=TreatyKind.JointWar,target=2});Check(joint.status==1&&w.AtWar(0,2)&&w.AtWar(1,2),"joint war commits both allies");
  w=Setup();w.turn=6;w.DiplomacyAI();Check(w.offers.Any(o=>o.from==1&&o.to==0&&o.status==0)&&w.HasAccess(1,2),"AI initiates player offers and negotiates with rival");Check(w.Valid(),"valid active diplomacy state");w.offers[0].givePerTurn=-1;Check(!w.Valid(),"malformed offers rejected");
 }
}
}
